    "question": "我が国の食料安全保障の強化に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。なお、データは「令和5年版 食料・農業・農村白書」による。\n\nA．我が国の主要農産物の輸入は特定国に依存している。令和4年の我が国の農産物輸入額を国別にみると、中国が最も高く、次いで米国、豪州、カナダ、タイ、ブラジルの順で続いており、上位6か国が占める輸入割合は9割程度となっている。また、我が国は、化学肥料原料の多くを輸入しており、令和3肥料年度＊は、りん酸アンモニウムや塩化加里、尿素のそれぞれ約6割を輸入している。\n\nB．令和2年3月に閣議決定した「食料・農業・農村基本計画」では、食料国産率について、令和12年度までに供給熱量ベースで45％、生産額ベースで75％に向上させる目標を定めている。なお、令和3年度の食料自給力指標は、「米・麦中心の作付け」及び「いも類中心の作付け」のいずれの試算でも、日本人の平均的な推定エネルギー必要量を上回っている。\n\nC．農林水産省は、不測の要因により食料供給に影響が及ぶ可能性のある事態に対処するため、平成24年9月に「緊急事態食料安全保障指針」を定めた。また、不測の事態を具体的に想定した上で、同指針に基づく対応やその実施手順の実効性を検証するため、食料の供給減少等を想定したシナリオに基づき、シミュレーション演習を実施している。\n\nD．政府は、米の国内生産量の減少によって供給が不足する事態に備え、100万 t程度の米の備蓄を行っている。また、海外における不測の事態の発生による供給途絶等に備えるため、食糧用小麦については外国産食糧用小麦の需要量の2.3か月分を、飼料穀物についてはとうもろこし等100万 t程度を民間で備蓄している。\n\n＊ 肥料の品質の確保等に関する法律に基づく肥料の管理年度（7月～翌年6月）",
