    "question": "我が国の農業を支える農業関連団体に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。なお、データは「令和5年版 食料・農業・農村白書」による。\n\nA．農業協同組合は、協同組合の一つで、農業協同組合法に基づいて設立されており、農業者等の組合員により自主的に設立される相互扶助組織である。令和3年度における総合農協の組合員数は約1036万人で、非農業者である准組合員は増加傾向となっている。\n\nB．農業委員会は、都道府県ごとに設置されている行政委員会である。農業委員会は、農地の権利移動の許可等を審議するほか、農業者の所得向上に向け、農産物の販売や生産資材の供給を行っている。\n\nC．土地改良区は、ほ場整備などの土地改良事業を実施するとともに、農地の利用集積や遊休農地の解消、新規参入の促進といった農地利用の最適化活動の事務局を担っている。小規模な土地改良区では、技術者の雇用や業務の実施が困難な場合もあることから、令和4年度から1県1組織化を推進している。\n\nD．農業共済制度は、各地域に設立された農業共済組合、県単位の農業共済組合連合会、国の3段階で運営されてきており、各組合が農業者に対する資金の貸付けや貯金の受入れ、病院経営等を行っている。農業経営の安定を図るため、農業者は必ず農業共済組合へ加入することとなっている。",
