      "エ": "Bは妥当だが、Dの液状化で生じる変化は逆である。飽和した緩い砂が締まろうとすると間隙水圧が高まり、有効応力が低下する。",
      "オ": "Cの最大乾燥密度と最適含水比の説明は妥当である。Dは間隙水圧と有効応力の変化をともに逆に述べている。"
