    "difficulty": 3,
    "question": "土木材料・製品に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA．複合材料とは、3種類以上の素材を組み合わせることで、単独の材料では得られない強度、剛性、靱性などの特性を獲得した材料のことである。強化プラスチック複合管（FRPM管）は、内外面に圧縮強度に優れた複合材料である繊維強化プラスチック、中間層に引張強度に優れた樹脂モルタルなどを用いて、複層構造にした管であり、耐久性、耐食性、耐電食性に優れている。\n\nB．プレストレストコンクリートとは、鉄筋コンクリート構造の欠点であるコンクリートのひび割れの防止又は制御などを目的に、鉄筋の代わりに鋼材を配置し、この鋼材にあらかじめ圧縮応力をかけておくことで、荷重によってコンクリートに発生する圧縮応力を相殺させるものである。プレストレスを与える方法として、プレテンション方式、プレキャスト方式がある。\n\nC．高分子材料は、一般に分子量が1万を超える化合物で、ゴム、セルロースなどの天然高分子材料と、合成樹脂や合成繊維などの合成高分子材料がある。合成樹脂であるエポキシ樹脂は、プラスチックの原料として用いられ、加熱を続けると硬化し、再加熱しても軟化しない熱硬化性を有しており、接着剤やコンクリートの補修材として利用される。\n\nD．瀝青は、常温では固体又は半固体の状態で、加熱により徐々に軟化して液体状になる物質であり、アスファルトがその代表的な物質である。アスファルトは、一般に温度によって性質が変化するため、硬さを評価する針入度、軟化しやすさを示す軟化点及び伸びやすさを示す伸度などのアスファルト試験により、性状を把握する。",
