    "question": "次は、静水圧に関する記述であるが、ア、イに当てはまるものの組合せとして最も妥当なのはどれか。\n\n「図のように、水面から30°だけ傾斜した任意の平面に対し、その傾斜方向に s 軸をおく。取水口門扉は s 軸の原点（水面との交点）から4.0 mの間であり、幅1.0 mの矩形である。ここで、取水口門扉に作用する水圧の作用点（圧力の中心）までの水深 h_c［m］を求めたい。門扉の厚さ・密度ともに均一であれば、矩形門扉に作用する全水圧 P は門扉の図心に垂直に作用する水圧にその面積を乗じた値となる。よって、全水圧 P は［ア］となる。\n　全水圧 P が作用点一点に垂直に作用するとしたとき、s 軸上の原点から作用点までの距離を s_c とすると、全水圧モーメントは P・s_c となる。また、s 軸に直交する微小領域 ds に作用する水圧のモーメントを門扉の領域全体にわたって積分すると全水圧モーメント P・s_c と等しい値が得られる。そのため、この関係から s_c を算出することができる。得られた結果を作用点の水深 h_c に換算すると、h_c は［イ］［m］と求められることになる。\n　ただし、水の密度を ρ［kg/m³］、重力加速度の大きさを g［m/s²］とする。」",
