    "question": "水路工に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA．水路の設計に当たっては、開水路や管水路ごとに設計流量、設計水位又は設計水圧を設定する。一般に、設計流量は計画最大流量を用い、設計水位又は設計水圧は最多頻度流量を通水する水位又は水圧とするが、クローズド形式の管水路の場合、設計水圧は水撃圧の値となる。\n\nB．流速の設定に当たっては、土砂の堆積や水中植物の繁茂が生じない最大許容流速を考慮する。なお、トンネル、暗渠、サイホン等で土砂の堆積が生じた場合、通水断面が狭まり設計流量が流れなくなること、堆積した土砂の排除が困難であること等を踏まえ、これらの施設内では、接続する開水路の流速よりも小さくする。\n\nC．開水路の通水断面の設定に当たっては、水理上の安全性を確保するため、原則として、設計流量に対する設計水面上に、水路の粗度係数の変動、流速水頭の静水頭への変換の可能性、水面の動揺等に対する余裕を加味する。\n\nD．等流水路の設計に当たっては、水面追跡が重要となる。等流水路における水面追跡では、逐次計算法などの手法を用い、既知の支配断面などを始点として、射流の場合は上流へ、常流の場合は下流へ向かって計算を進める。",
    "choices": {
      "ア": "C",
      "イ": "D",
      "ウ": "A、B",
      "エ": "A、C",
      "オ": "B、D"
    },
    "answer": "ア",
    "officialAnswerNumber": 1,
    "explanation": "Cのみが妥当である。水面の動揺や水路の粗度の変化などに備え、開水路には設計水面より上に余裕高を設ける。",
    "choiceExplanations": {
      "ア": "Cのみが妥当である。水面の動揺や水路の粗度の変化などに備え、開水路には設計水面より上に余裕高を設ける。",
      "イ": "水面形を追跡する際は、射流では上流側の支配断面から下流へ、常流では下流側の支配断面から上流へ計算する。Dではこの方向が逆である。",
      "ウ": "Aの設計水位等は最多頻度の流量だけを基準とするものではなく、閉鎖型管路の設計水圧には静水圧も考慮する。Bの堆積を防ぐための限度は最小流速である。",
      "エ": "Cは妥当だが、Aのクローズド形式の管水路の設計では、水撃圧だけでなく管路に常時作用する水圧も考慮する。最多頻度流量を通水する場合だけで必要な断面・圧力を評価できない。",
      "オ": "Bに挙げる土砂の堆積を避けるには、一定以上の流速を確保する必要がある。Dの水面追跡は、射流では下流方向、常流では上流方向に行う。"
    },
