    "difficulty": 3,
    "question": "我が国の農業水利施設に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。なお、データは「令和5年版 食料・農業・農村白書」による。\n\nA．受益面積を100 ha以上持つ基幹的農業水利施設については、令和3年3月末時点で、約7700か所のダム、取水工、用排水機場、農業集落排水施設等の基幹的施設及び40万 km以上の基幹的水路が全国で整備されている。\n\nB．基幹的農業水利施設の相当数は、戦後から高度経済成長期にかけて整備されてきたが、老朽化した施設の更新・改修が適切に行われてきた結果、標準耐用年数を超過している施設・延長の割合は、基幹的施設で全体の20％、基幹的水路で全体の10％に抑えられている。\n\nC．農業水利施設の健全度は、施設の機能や性能を評価する機能診断の結果に基づき、施設の変状等の程度を指標化した「健全度指標」を用いて、構造性能の観点から総合的に評価する。「健全度指標」は、S-1からS-5までの5段階で評価するが、この数字が大きいほど、施設の機能が健全な状態であることを表している。\n\nD．農業水利施設の耐震化と維持管理費用の低減に向けて、施設の老朽化によるリスクを踏まえた点検、機能診断、監視等を行い、補修・更新等の様々な対策工法を比較検討することにより、適切な対策を計画的かつ効率的に実施するストックマネジメントが推進されている。この結果、令和3年度の農業水利施設の漏水等の突発事故発生数は、1990年代と同水準に抑えられている。",
