      "イ": "中性化は、二酸化炭素がセメント水和物と炭酸化反応を起こし、細孔溶液中の pH を上昇させることで、コンクリートの強度や弾性係数などの物理的性質が劣化するとともに、鋼材の腐食が促進され、コンクリートのひび割れやはく離、鋼材の断面減少を引き起こす劣化現象である。",
