    "difficulty": 3,
    "question": "基礎工に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA．直接基礎は、地表近くの支持力の強い地盤を利用し、直接その上に基礎を施工するもので、フーチング基礎やケーソン基礎などの形式がある。直接基礎の設計に当たっては、地盤の支持力、滑動の2項目の安定に留意すれば十分である。\n\nB．杭基礎は、伝達の機構によって支持杭と摩擦杭に大別され、一般に、支持層が比較的深い場合は摩擦杭が適用される。また、工法としては、工場で生産された杭を用いる既製杭工法と、施工現場で鉄筋コンクリート杭を造成する場所打ち杭工法に大別される。\n\nC．軟弱地盤とは、構造物の基礎地盤として十分な地耐力を有しない地盤で、一般に、標準貫入試験で測定する N 値が一定値以下となる地盤をいう。軟弱地盤の改良工法には、軟弱地盤の不良土を良質土に置き換える置換工法や、軟弱地盤の中に砂杭を設けて圧密促進を行うサンドドレーン工法など様々な種類があり、対象地盤の土質や改良目的に応じた工法を用いる。\n\nD．地表面下に構造物を施工する際に行う土留め工において留意すべき現象として、軟弱な粘土質地盤において土留めの背面にある土砂が沈下しその影響で掘削底面が盛り上がってくるボイリング、砂質地盤において地下水位以下まで掘削する場合に水位差の影響で地下水と共に土砂が沸騰するように掘削底面に吹き上がってくるヒービングがある。",
