    "question": "次は、地下水利用に関する記述であるが、ア、イ、ウに当てはまるものの組合せとして最も妥当なのはどれか。\n\nDepletion of groundwater is often attributed to agricultural ［ア］. Depletion leads to a multitude of externalities, including drying up of groundwater-dependent wetlands and watercourses via reduced baseflows and compaction of compressible earth layers, with ensuing land subsidence＊1, downward migration of low-quality groundwater, and saline intrusion into aquifers＊2 and surface water systems along coastal plains.\n\nTerrestrial observations and satellite data have demonstrated, or made plausible, that numerous aquifers are being exploited at rates that are inducing rapid depletion and associated social and environmental externalities. This includes several of the world’s 37 major aquifer systems. High abstraction rates for ［イ］ agriculture are concentrated in arid and semi-arid regions, where population growth and expansion of ［イ］ areas have led to rapid growth in water demand.\n\nGroundwater exploitation has been driven by ［ウ］, such as its capacity to provide flexible, on-demand irrigation to support wealth-creating agriculture and the easy availability of inexpensive pumps, drilling technologies and energy, often underpinned by government support and subsidy programmes.\n\n＊1 land subsidence：地盤沈下\n＊2 aquifer：帯水層",
