    "officialAnswerNumber": 5,
    "explanation": "止水壁を堰体の上流側で地中に設けると、基礎地盤を通る浸透経路が長くなり浸透流を抑えられる。地盤から土粒子が流出するパイピングを防ぎ、堰の安全性を確保する役割がある。",
