    "difficulty": 3,
    "question": "排水に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA．洪水時のピーク流出量を求めることができる合理式は、洪水到達時間内の平均有効降雨強度、流域面積及び透水係数を用いて算定する式で、適用範囲の上限は、土地利用が一様とみなされる範囲（10 km²未満）までと考えられる。\n\nB．洪水時の降水量のうち直接流出する成分を有効降雨といい、流出成分にならない成分を損失降雨という。単位時間ごとの有効降雨の推定法には、浸入能曲線法、雨水保留量曲線（損失雨量曲線）法などの方法がある。\n\nC．自然排水や機械排水を計画する場合、対象とする流域（傾斜地域又は湛水域）に応じて適切な計算モデルを選定し、洪水ハイドログラフを求める。なお、傾斜地域は一時貯留又は洪水による湛水が発生しない地域であり、湛水域は一時貯留又は洪水による湛水が発生する地域である。\n\nD．雨水流モデルは、流域を斜面と河道に分割し、それぞれの流れを運動方程式と連続式で再現し洪水ハイドログラフを求めるモデルである。このモデルは観測降雨量に対する直接流出量を求める集中型モデルである。",
    "choices": {
      "ア": "A、B",
      "イ": "A、D",
      "ウ": "B、C",
      "エ": "B、D",
      "オ": "C、D"
    },
