    "difficulty": 3,
    "question": "我が国の水資源及び水循環に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。なお、データは「令和4年版 日本の水資源の現況」（国土交通省）による。\n\nA．令和3年の我が国の年降水量（全国51地点の平均）は、約1800 mmであり、世界（陸域）の年降水量の約1.5倍である。一方、年降水量に国土面積を乗じ全人口で除した我が国の一人当たり年降水総量は、世界のそれの4分の1程度である。\n\nB．近年は、日降水量100 mm以上及び日降水量200 mm以上の日数は共に増加している一方、日降水量1.0 mm以上の日数は減少している。これらの結果は、大雨の頻度が増えて洪水のリスクが高まり、降水がない日も増えて渇水のリスクが高まる特徴を示している。\n\nC．令和元年の農業用水量は約530億 m³であり、その9割以上を水田灌漑用水が占める。近年は水稲の作付面積が減少している上、水の反復利用の推進等による効率化により、農業用水量は着実に減少している。例えば、平成17年から令和元年にかけて10％以上減少している。\n\nD．近年の頻発化・激甚化する水災害に対応するため、流域のあらゆる関係者が一丸となって対策を行う「流域治水プロジェクト」が進められている。農業関係では、出水前に農業用水路に貯留した水の放流による空き容量の確保（事前放流）、出水中に水田への積極的な導水による放流ピーク量の低減（田んぼダム）を実施している。",
    "choices": {
      "ア": "A、B",
      "イ": "A、C",
      "ウ": "B、C",
      "エ": "B、D",
      "オ": "C、D"
    },
    "answer": "ア",
    "officialAnswerNumber": 1,
    "explanation": "AとBが妥当である。日本は面積当たりの降水量が多くても人口一人当たりでは世界平均より少なく、大雨の日と雨の少ない日がともに増えると洪水と渇水の両方のリスクが高まる。",
    "choiceExplanations": {
      "ア": "AとBが妥当である。日本は面積当たりの降水量が多くても人口一人当たりでは世界平均より少なく、大雨の日と雨の少ない日がともに増えると洪水と渇水の両方のリスクが高まる。",
      "イ": "Aは妥当だが、Cの2019年の農業用水量は約533億 m³で、2005年からの減少幅は10％に達しない。水田が大半を占める点と、期間中の減少幅は区別する。",
      "ウ": "Bの大雨の日数と降水日数の傾向は妥当である。Cは農業用水量の減少幅を大きく述べている。",
      "エ": "Bは妥当だが、Dの事前放流で空き容量を確保するのは、例えば農業用ダムである。田んぼダムは、水田に降った雨水を一時的にためて流出を遅らせる取組である。",
      "オ": "Cの2005年からの減少幅は10％未満である。Dも、田んぼダムでは雨水を水田に一時貯留し、排水口で水の流出を抑えるという仕組みが異なる。"
    },
