    "question": "土の物理性及び試験法に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA．土壌水分量は、土壌を60℃で24時間乾燥させた状態を水分量0とし、体積含水率、含水比、飽和度などによって表される。土壌水分量の測定は、湿潤土と乾燥土の質量を乾燥炉などを用いて測定する直接法と、硝酸などの溶質濃度をセンサで測定し検量線に基づいて推定する間接法に大別される。\n\nB．農作業機械の走行性に関わる地盤の性質は地耐力として把握され、一般にコーン貫入試験に基づくコーン指数で表す。コーン指数とは、コーンペネトロメータによる静的貫入法によって求められる値であり、水田では耕うん時・収穫時と、代かき時で測定する深さが異なる。\n\nC．透水係数とは、土中の水の流速を示すダルシー則の比例定数である。不飽和透水係数は、実験室において定水位法（定水頭法）又は変水位法（変水頭法）によって求められる。定水位法は透水性の比較的小さい場合に用いられ、変水位法は透水性の大きい場合に用いられる。\n\nD．有機物含有量とは、土に含まれる動植物の遺体とバクテリア等により分解された腐植などの有機物を合わせた量で、この量を炉乾燥土の質量で割った百分率で表す。その試験法の一つとして、炉乾燥土を700～800℃に加熱することにより減少した質量を有機物量の推定値とする強熱減量法がある。",
