    "question": "我が国の農業構造に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。なお、データは「令和5年版 食料・農業・農村白書」による。\n\nA．令和3年度の新たに荒廃農地から再生利用された面積は、新たに発生した荒廃農地面積に比べ大きく、荒廃農地の面積は大幅に減少した。また、令和3年の作付（栽培）延べ面積は農地面積よりも大きく、耕地利用率は100％以上である。\n\nB．令和4年に成立した改正農業経営基盤強化促進法＊では、都道府県が担い手への農地集積の目標面積を定め、目指すべき将来の農地利用の姿を作成することとしている。また、同法においては、市町村が目標地図を含めた地域計画を作成し、目標地図の素案については、土地改良区が作成することとなっている。\n\nC．認定農業者制度は、農業者が経営発展に向けて作成した農業経営改善計画を市町村等が認定する制度である。近年の認定農業者数は減少傾向にあるものの、農業経営体に占める認定農業者の割合は増加傾向で推移している。また、農業経営改善計画の認定数を営農類型別にみると、65歳以上の階層では、稲作の単一経営が全体の4分の1程度を占めている。\n\nD．農林水産省では、効率的かつ安定的な農業経営を育成・確保するため、令和5年度までに、法人経営体数を5万法人にする目標を設定している。令和4年の農業経営体数に占める法人経営体の割合は5％未満だが、法人経営体は経営耕地面積が大きい層の割合が高く、経営耕地面積に占める法人経営体の面積割合は4分の1程度と高くなっている。\n\n＊ 農業経営基盤強化促進法等の一部を改正する法律",
