    "difficulty": 3,
    "question": "換地処分及び農地の集積に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA．換地処分は土地の権利関係の再編成を行う手段であるが、権利関係をどのように再編成するかは土地改良事業の目的に則して決められる。土地改良事業の目的は「農用地の集団化その他農業構造の改善に資すること」であり、具体的には農用地の集団化、担い手（育成すべき経営体）へ集積された農用地の流動化を含み、一時利用地指定による土地利用の秩序化が目標となる。\n\nB．換地処分の基本的な構造は、従前の土地と換地との間に対応関係があることにある。そのため、①従前の農用地は非農用地区域外に、非農用地は非農用地区域内に換地を定めなければならないこと、②地積、土性、水利等条件を総合的に勘案して従前の土地と換地が同等であること、③基準とする地積に対する換地面積の増減割合は2割未満であることの三つの要件のうち二つ以上を満たす必要がある。\n\nC．対応関係がない特例扱いのものとして、対応する従前の土地がない換地を定める創設換地等がある。創設換地の原資となる土地の生み出し方は異種目換地によるものと、不換地及び特別減歩見合いによるものとがある。このうち後者は事業参加資格者の3分の2以上の同意があれば全員に強制的に課されるため、その適用対象は土地改良施設や事業区域内の農業者の大部分が利用する施設に限られる。\n\nD．農地中間管理機構（以下「機構」という。）が農地所有者から借り受ける農地は集積や基盤整備が行われていない場合が多く、そうした農地は担い手の経営規模拡大に機能しにくい。機構による担い手への農地の集積・集約化を加速するため、機構が借り入れている農地を対象に、都道府県は農業者からの申請や費用負担、同意を要さずに、換地処分や農地の基盤整備を実施することができる。",
