      "イ": "不換地や特別減歩は、その土地の所有者の申出又は同意に基づく。事業参加資格者の3分の2以上が同意すれば全員に一律に課せられるという記述は異なる。",
      "ウ": "Dのみ妥当である。農地中間管理機構が借り入れる農地について、都道府県が一定の要件の下で農業者の申請・同意・費用負担を要さず基盤整備を行う制度がある。",
