      "イ": "イとウは妥当である。アの transferable は「譲渡できる」という意味で、大気の所有権が存在しないという文脈では absent となる。",
      "ウ": "アは、大気に所有権がないことを表す absent である。汚染への課税は外部性を内部化する手段なので、イの cause も適さない。",
      "エ": "大気の所有権は存在せず、国内の汚染に課税することで外部性を内部化できる。一方、EUは非加盟国に炭素税の導入を命じられないので、absent、internalize、cannot が入る。",
      "オ": "アの absent は妥当だが、汚染税の目的は外部性を生じさせることではなく、その費用を汚染者に負担させることである。EUの指令が及ばない非加盟国については cannot が入る。"
