      "エ": "「小さな拠点」とは地域住民が地方公共団体や事業者、各種団体と協力・役割分担をしながら、行政施設や学校、郵便局等を分散して設置し、周辺集落との間をネットワークで結ぶものである。関係省庁は「小さな拠点」の形成及び展開に向けて、廃校施設等の活用による地域間交流拠点の整備、外縁の過疎集落から「小さな拠点」となる集落への空き家等の活用による集団移転の促進等を行っている。",
