    "difficulty": 3,
    "question": "我が国の防災・減災、国土強靱化に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。なお、データは「令和5年版 食料・農業・農村白書」による。\n\nA．国土強靱化とは、災害の発生後の復興段階において、次の災害発生に備えて、より災害に対して強靱な地域づくりを行うという考え方であり、平成27年の第3回国連防災世界会議において提唱されたことを契機に、我が国にも取り入れられた。国土強靱化の対象範囲は行政のハード面の取組であり、これに含まれないソフト面の取組や民間の取組との連携が今後の課題となる。\n\nB．近年の自然災害において、我が国の農林水産業には甚大な被害が発生しており、平成25年以降の過去10年では、農林水産関係の被害額は一貫して増加傾向にある。また、大規模な自然災害が生じた場合、政府は、地方自治体からの申請に基づき、各省庁による災害査定見込額の算定前に当該災害を激甚災害に指定し、地方財政の負担軽減等の措置を講じることができる。\n\nC．令和3年3月に策定された土地改良長期計画においては、農村地域の高齢化や人口減少、自然災害の頻発化や激甚化が今後更に見込まれる中、農業政策と地域政策を支える視点として、政策課題の一つに「農業・農村の強靱化」を位置付けている。また、この政策課題の政策目標として、頻発化・激甚化する災害に対応した排水施設整備・ため池対策等の取組を掲げている。\n\nD．都道府県知事は、ため池工事特措法＊に基づき、決壊により人的被害が及ぶことが懸念される農業用ため池を防災重点農業用ため池として指定し、防災工事等を集中的・計画的に進めるための防災工事等推進計画を策定している。なお、防災工事等が実施されるまでの間は、ハザードマップの作成、監視・管理体制の強化等が重要であり、令和3年度末時点で全体の半数以上の防災重点農業用ため池でハザードマップが作成されている。\n\n＊ 防災重点農業用ため池に係る防災工事等の推進に関する特別措置法",
