    "difficulty": 3,
    "question": "我が国の農村における所得と雇用機会の確保に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。なお、データは「令和5年版 食料・農業・農村白書」による。\n\nA．野生鳥獣による農作物被害は、営農意欲の減退をもたらし耕作放棄や離農の要因ともなっている。例年イノシシによる被害額が最も大きいものの、このような害獣を野生鳥獣肉（ジビエ）として利用することは食文化を豊かにし、地域を活性化させ、所得を生み出す地域資源にもなる。ジビエの利用量は増加傾向にあるものの、ペットフードとしての利用が最も多く、食肉としての利用拡大のため、より安全なジビエの提供と消費者の安心の確保を図ることが必要である。\n\nB．農泊とは、農山漁村地域の農家や漁師宅に宿泊し、滞在中に伝統的な生活体験や食事、地域の人々との交流を通じて、その土地の魅力を味わう旅行のことであり、リゾートホテルや温泉旅館に宿泊するのみの場合は含まれない。農山漁村への長時間の滞在と消費を促すことにより地域の活性化と所得向上を図るものであり、令和4年度末までに全国約60の農泊地域が観光庁によって認定されており、農林水産省がこれらを支援してきている。\n\nC．障害者等の農業分野での雇用・就労を推進する農福連携は、農業、福祉両分野にとって利点があるものとして各地で取組が進んでいる。厚生労働省は、誰もが農業体験を通じて農業の持つ多面的な機能を享受でき、障害者・高齢者等の多世代・多属性の利用者が交流・参画する農園を「ノウフク JAS」と位置付け、その「ノウフク JAS」の整備・利用を農林水産省が推進するという省庁間連携により障害者等への支援が図られている。\n\nD．「農山漁村発イノベーション」とは、農林漁業者が加工・販売等に取り組む従来の6次産業化の取組を発展させて、地域の文化・歴史や森林、景観など農林水産物以外の多様な地域資源も活用し、農林漁業者はもちろん、地元の企業なども含めた多様な主体の参画により、観光・旅行や福祉等の他分野と組み合わせて新事業や付加価値の創出を図る取組である。",
