      "オ": "水田は硝化反応が起こりやすい環境にあり、窒素除去が行われるため、水質浄化機能を果たしているとされる。これは一般に、湛水状態にある水田土壌において、表層数 mmから1～2 cmの還元層で無機化された窒素が、その直下の酸化層において硝化され、窒素ガス（N₂）として大気中に放出されることによる。"
