    "difficulty": 3,
    "question": "機械工作に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA．旋盤による工作は、工作物を主軸に装着して回転させ、種々の形状をしたブレードと呼ばれる刃物によって切削を行う。ブレードは往復台上に固定され、往復台は手送り又は自動送りによって縦方向、横方向、上下方向に移動する。\n\nB．ボール盤は、主軸にドリルなどの工具を取り付けて回転させ、これを下降させて工作物に穴あけ、さらもみ、めねじ切りなどの加工をする工作機械である。ボール盤で利用するドリルは種々あるが、一般に広く用いられるのはツイストドリルで、主軸へ装着する部分の形状にはストレートシャンクとテーパーシャンクがある。\n\nC．フライス盤は、フライスという砥石を使用して平面、円周、溝、特殊曲面等の広範囲にわたる加工を行う。立フライス盤は、主軸を水平に配置し、工作物に種々の送りを与えて加工するフライス盤をいう。\n\nD．金属を切削加工するときには熱が発生する。この熱で刃先の温度が上昇し、刃物先端の硬さが低下し、切削能率や寸法精度が悪化する場合がある。このような問題を解消するため、潤滑作用、冷却作用及び切りくずの除去作用等のある「金属加工油剤」とも呼ばれる切削液が用いられる。",
