    "difficulty": 3,
    "question": "図1は、3個の押しボタン（PB1、PB2、PB3）により2個のランプ（L1、L2）の点灯とリレー（R1）を制御する回路をシーケンス図にしたものである。図2に示すタイムチャートに沿って t0 から順に各ボタンを操作した場合に、L1 と L2 が同時に点灯する期間 Dn（n = 1, 2, …, 6）のみを全て挙げているのはどれか。\n\nただし、電源は P から N への直流であり、タイムチャートは各ボタンが導通している状態を ON とし、図1は初期状態 t0 を示している。",
