      "イ": "D1では初期状態、D6では自己保持が解除された後なので、どちらもR1は励磁されていない。PB3が導通してL2が点灯するが、L1は消えている。",
      "ウ": "D2でPB1が導通してL1が点灯し、D3ではPB2とR1の常開接点を通じて点灯を保持する。R1が励磁されている間はL2側の接点が開いている。",
      "エ": "D4ではPB1がONなのでL1が点灯し、R1も励磁されている。PB3が導通していてもL2側のR1の常閉接点は開いているため、L2は点灯しない。",
      "オ": "D5ではPB1もPB2もOFFとなり、R1の自己保持が解除されてL1が消える。PB3もOFFなので、L2も点灯しない。"
