      "イ": "A：アーク　B：エレクトロスラグ　C：フラックス　D：水素",
      "ウ": "A：アーク　B：エレクトロスラグ　C：溶加材　D：アセチレン",
      "エ": "A：レーザービーム　B：スポット　C：フラックス　D：アセチレン",
