    "question": "次は、トラクタのけん引性能に関する記述であるが、A～Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\n「トラクタの性能は、けん引性能と駆動性能に分けられる。けん引性能は、［A］、プラウ、トレーラなどの作業機によるけん引作業時の性能となり、トラクタのけん引力は、［B］と走行抵抗の差として表現される。車輪トラクタの場合、走行抵抗の大部分は［C］であり、圃場において［C］の主たる要因は車輪下の土の締め固め抵抗である。また、圃場でのけん引作業では、車輪と接地面との間に滑りが生じ、滑り率として算出される。滑り率は、けん引力が大きくなるにしたがって増大し、走行状態が不安定になることから、圃場でのトラクタによるけん引作業においては、一般に、滑り率が［D］の状態で実施される。」",
