    "question": "次は、田植機及び水稲直播技術に関する記述であるが、A～Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\n「田植機は育苗施設で生育された土付き苗を水田へ移植する機械であり、植付け機構は［A］式と［B］式に大別される。［A］式は［A］軸の回転軌跡の上方で分苗し、最下点近くで地中へ挿苗する。［B］式は植付けづめが回転ケースに2個装着され、交互に分苗、挿苗を行うことにより、高速運動が可能となるため、乗用型田植機に用いられる。\n　水稲直播技術は移植やその準備に必要な作業を省略することができるため、省力化が期待される。直播技術は泥水の有無で乾田直播と湛水直播に大別される。乾田直播は、一般に、ロータリシーダや［C］等により播種し、湛水直播は種子に酸素を供給するために［D］によりコーティングされた種子を用いる場合がある。」",
