    "question": "人工知能（Artificial Intelligence: AI）に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA．AIには幅広い概念が含まれ、専門家の間でも定義が定まっていない。その理由の一つは、「知能」の明確な定義が困難なためである。AIには特定のことだけを処理できる特化型AIと、人間の行っている幅広い知的処理に対応できる汎用型AIがある。\n\nB．機械学習には方向性や目標を示し、ランダムな試行錯誤を通じてモデルを構築する教師なし学習、ラベル付けした出力変数である解答を用意して、その中からパターンを抽出してモデルを構築する教師あり学習、出力変数にラベルを付けず解答を用意しない強化学習がある。\n\nC．ニューラルネットワークはパーセプトロンというアルゴリズムを起源とし、入力層、中間層（隠れ層）、出力層からなる。ネットワーク内の信号伝達において、パーセプトロンの活性化関数はステップ関数であるが、一般に、ニューラルネットワークではシグモイド関数や ReLU 関数が用いられる。\n\nD．養豚では肥育豚の画像からAIを用いて体重や枝肉量を推定し、さらに個体識別が可能な機器が実用化されている。また、採卵養鶏においては、鶏舎内を自律走行し、ケージ内の病気に罹患した鶏を画像から検出し、作業者に通知するロボットが実用化されている。",
