    "question": "一定の温度で食品を加熱殺菌すると時間とともに微生物の生存数 N は減少する。生存率と加熱時間との関係は次の式で表され、これを生存曲線という。\n\nN/N₀ = e^(−k_dt)\n\nなお、N₀ は初期生存数、N は生存数、k_d は死滅速度定数、t は加熱時間（min）とする。\nある微生物の懸濁液を加熱したとき、加熱時間と生存率は図のようになった。k_d と微生物の死滅特性を表す一つの指標としての D 値（decimal reduction time）との組合せとして最も妥当なのはどれか。\nただし、e は2.72、log₁₀ e は0.434とする。",
