      "イ": "グラフでは10分で生存率が10⁻²になるので、1桁減るD値は5分である。log₁₀(N/N₀) = −k_d × t × log₁₀ e より、k_d = 0.2/0.434 ≈ 0.461 min⁻¹となる。",
