      "イ": "AとDが妥当である。光補償点では呼吸によるCO₂放出と光合成による吸収が釣り合い、水平に一様とみなした群落内では上方に積算した葉面積に応じて光が指数的に減衰する。",
      "ウ": "BではC₃とC₄の応答を取り違えており、C₄植物はCO₂濃縮機構によって低濃度域でも光合成を行いやすい。Cの最適温度は、CO₂濃度や光条件によって変わり得る。",
      "エ": "Dの群落内の光は積算葉面積に応じて減衰する。BのCO₂固定ではRubiscoは酵素であり、再生するCO₂受容体であるRuBPとは別である。",
