    "difficulty": 3,
    "question": "次は、リモートセンシングに関する記述であるが、A～Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\n「リモートセンシングで利用されるセンサは、受動型センサと能動型センサに分けられる。受動型センサはターゲットからの太陽光の反射又はターゲットから放出される放射エネルギーを観測する。代表的なものに、地表での空間解像度が数十 mから100 m程度で、マルチスペクトルデータの取得が可能な、［A］がある。能動型センサはセンサ自体が地上に電磁波を照射し、その反射波を受信して情報を取得する。代表的なものに、レーザー光を使用した［B］、マイクロ波を使用した［C］がある。\n　地表面における植生の状態を表す指標として、赤と近赤外領域の反射率を用いて求められる［D］がよく用いられている。」",
    "choices": {
      "ア": "A：Landsat　B：合成開口レーダ　C：ライダ　D：NDVI",
      "イ": "A：Landsat　B：合成開口レーダ　C：ライダ　D：NDSI",
      "ウ": "A：Landsat　B：ライダ　C：合成開口レーダ　D：NDVI",
      "エ": "A：AVHRR　B：合成開口レーダ　C：ライダ　D：NDSI",
      "オ": "A：AVHRR　B：ライダ　C：合成開口レーダ　D：NDSI"
    },
    "answer": "ウ",
    "officialAnswerNumber": 3,
